def rational_eval(expr):
    from fractions import Fraction
    tokens, i = [], 0
    while i < len(expr):
        c = expr[i]
        if c in " \t":
            i += 1
        elif c in "0123456789":
            j = i
            while j < len(expr) and expr[j] in "0123456789":
                j += 1
            tokens.append(("n", int(expr[i:j])))
            i = j
        elif c in "+-*/^()":
            tokens.append((c, None))
            i += 1
        else:
            return "error"

    class Bad(Exception):
        pass

    pos = 0

    def peek():
        return tokens[pos][0] if pos < len(tokens) else None

    def take():
        nonlocal pos
        pos += 1
        return tokens[pos - 1]

    def expression():
        value = term()
        while peek() in ("+", "-"):
            op = take()[0]
            right = term()
            value = value + right if op == "+" else value - right
        return value

    def term():
        value = unary()
        while peek() in ("*", "/"):
            op = take()[0]
            right = unary()
            if op == "*":
                value = value * right
            else:
                if right == 0:
                    raise Bad()
                value = value / right
        return value

    def unary():
        if peek() == "-":
            take()
            return -unary()
        return power()

    def power():
        base = atom()
        if peek() == "^":
            take()
            exponent = unary()
            if exponent.denominator != 1 or abs(exponent) > 64 or (base == 0 and exponent < 0):
                raise Bad()
            return base ** int(exponent)
        return base

    def atom():
        kind = peek()
        if kind == "n":
            return Fraction(take()[1])
        if kind == "(":
            take()
            value = expression()
            if peek() != ")":
                raise Bad()
            take()
            return value
        raise Bad()

    try:
        value = expression()
        if pos != len(tokens):
            raise Bad()
    except Bad:
        return "error"
    if value.denominator == 1:
        return str(value.numerator)
    return str(value.numerator) + "/" + str(value.denominator)

