            free.append((cursor, a))
        cursor = max(cursor, b)
    if cursor < end:
        free.append((cursor, end))
    fmt = lambda m: f"{m // 60:02d}:{m % 60:02d}"
    return [[fmt(a), fmt(b)] for a, b in free if b - a >= min_len]

